-- Oghoule's Warpath : textes d'ambiance a l'entree des donjons (genere par lore.py). %s = nom du personnage.
local _, ns = ...
ns.Lore = {
    bfd = { fr = "%s, au bord de la mer, le vieux temple elfe de Blackfathom a sombré dans les ténèbres : le Marteau du crépuscule y vénère Aku'mai, une bête des abysses nourrie de haine. L'Anneau terrestre de Zoram'gar compte sur ton acier. Plonge dans les eaux noires et brise ce culte avant que l'ancien dieu ne s'éveille !", en = "%s, by the sea, the old elven temple of Blackfathom has fallen into darkness: the Twilight's Hammer worships Aku'mai there, a beast of the abyss fed on hatred. The Earthen Ring at Zoram'gar is counting on your steel. Dive into the black waters and break this cult before the old god wakes!" },
    brd = { fr = "%s, au cœur de la montagne Blackrock, l'empereur Dagran Thaurissan règne sur les nains Sombrefer au nom de Ragnaros. On dit que la princesse Moira est retenue dans son palais, et Thrall veut savoir pourquoi. Enfonce les forges de l'ombre et que la cité de feu apprenne le nom de la Horde !", en = "%s, in the heart of Blackrock Mountain, Emperor Dagran Thaurissan rules the Dark Iron dwarves in Ragnaros' name. They say Princess Moira is held in his palace, and Thrall wants to know why. Smash through the shadow forges and let the city of fire learn the name of the Horde!" },
    dalaran = { fr = "%s, derrière son dôme violet, la cité des mages est déchirée par une magie hors de contrôle, et des ombres d'archimages hantent ses tours. Même l'ennemi d'hier implore de l'aide. Entre dans Dalaran, brise la source du désordre et montre aux mages ce que vaut une lame de la Horde !", en = "%s, behind its violet dome, the city of mages is torn apart by magic gone wild, and the shades of archmages haunt its towers. Even yesterday's enemy begs for aid. Enter Dalaran, shatter the source of the chaos and show the mages what a Horde blade is worth!" },
    dm_e = { fr = "%s, dans les ruines d'Eldre'Thalas, les satyres et les démons ont fait de l'aile est un repaire corrompu. Alzzin le Modeleur des terres sauvages y tord la nature à sa volonté. Entre dans Dire Maul et arrache cette racine pourrie !", en = "%s, in the ruins of Eldre'Thalas, satyrs and demons have turned the east wing into a corrupted lair. Alzzin the Wildshaper bends nature to his will there. Enter Dire Maul and tear out this rotten root!" },
    dm_w = { fr = "%s, dans l'aile ouest de Dire Maul, les Bien-nés Shen'dralar se nourrissent encore de la puissance d'un démon emprisonné, Immol'thar. Leur prince Tortheldrin tient la cité d'une main avide. Brise leurs cristaux et fais tomber ces seigneurs d'un autre âge !", en = "%s, in the west wing of Dire Maul, the Shen'dralar Highborne still feed on the power of an imprisoned demon, Immol'thar. Their prince Tortheldrin grips the city with a greedy hand. Shatter their crystals and topple these lords of another age!" },
    excav = { fr = "%s, dans les marais des Wetlands, les fouilles ont percé un caveau des Titans que nul n'aurait dû ouvrir. Ses gardiens de pierre se sont réveillés, et les reliques qu'ils protègent pourraient changer le sort de la Horde. Descends dans les profondeurs et arrache ces secrets aux mains des anciens !", en = "%s, in the marshes of the Wetlands, the diggings have pierced a Titan vault no one should have opened. Its stone guardians have awakened, and the relics they guard could change the fate of the Horde. Descend into the depths and tear these secrets from the hands of the ancients!" },
    gnomer = { fr = "%s, la cité des gnomes n'est plus qu'un tombeau irradié, livré au traître Mekgineer Thermaplugg et à ses machines folles. Elle se trouve en plein territoire de l'Alliance : marche vite et frappe fort. Les gobelins d'Orgrimmar paient bien ceux qui reviennent de ces entrailles de métal !", en = "%s, the gnome city is now nothing but an irradiated tomb, left to the traitor Mekgineer Thermaplugg and his mad machines. It lies deep in Alliance territory: move fast and strike hard. The goblins of Orgrimmar pay well for those who return from these metal bowels!" },
    lbrs = { fr = "%s, au pied du pic Blackrock, les orcs de la Horde noire ont trahi tout ce que Thrall a reconstruit. Leurs seigneurs de guerre tiennent les étages inférieurs comme une forteresse. Écrase ces renégats et montre-leur ce qu'est la vraie Horde !", en = "%s, at the foot of Blackrock Spire, the orcs of the Dark Horde have betrayed all that Thrall rebuilt. Their warlords hold the lower halls like a fortress. Crush these renegades and show them what the true Horde is!" },
    mara_in = { fr = "%s, au plus profond de Maraudon, la princesse Theradras pleure encore Zaetar, et sa rage empoisonne Desolace tout entière. Sous les cascades, la terre elle-même te défie. Descends jusqu'à elle et rends enfin la paix aux esprits de cette terre !", en = "%s, in the deepest reaches of Maraudon, Princess Theradras still mourns Zaetar, and her rage poisons all of Desolace. Beneath the waterfalls, the earth itself defies you. Descend to her and finally bring peace to the spirits of this land!" },
    mara_out = { fr = "%s, Maraudon est la terre sacrée des centaures, souillée par la corruption de la princesse Theradras. Ses grottes de cristal grouillent de bêtes empoisonnées et de seigneurs déchus. Purge les ailes extérieures et ouvre la route vers le cœur de la terre !", en = "%s, Maraudon is the sacred ground of the centaur, defiled by Princess Theradras' corruption. Its crystal caves swarm with poisoned beasts and fallen lords. Purge the outer wings and open the way to the heart of the earth!" },
    rfc = { fr = "Écoute, %s : sous les pavés mêmes d'Orgrimmar, la Lame ardente a creusé son nid dans la lave. Ces cultistes vendent leur âme aux démons dont Thrall a libéré notre peuple, et Taragaman l'Affamé s'éveille dans les profondeurs. Descends dans la Faille de l'Ombre et purge ce chancre avant qu'il ne dévore la capitale de l'intérieur !", en = "Listen, %s: beneath the very streets of Orgrimmar, the Burning Blade has made its nest in the lava. These cultists sell their souls to the demons Thrall freed our people from, and Taragaman the Hungerer stirs in the depths. Descend through the Cleft of Shadow and burn out this rot before it devours the capital from within!" },
    rfd = { fr = "%s, dans les tertres de Razorfen, les huttes-épines se sont alliés au Fléau, et la liche Amnennar le Porte-froid règne sur leurs morts. Ce pacte impie menace toutes les Tarides. Descends dans le froid et ramène le crâne de la liche !", en = "%s, in the Razorfen barrows, the quilboar have allied with the Scourge, and the lich Amnennar the Coldbringer rules over their dead. This unholy pact threatens all of the Barrens. Descend into the cold and bring back the lich's skull!" },
    rfk = { fr = "%s, sous les ronces géantes nées du sang d'Agamaggan, les huttes-épines ont bâti leur forteresse. La matriarche Charlga Razorflank y prépare une guerre contre tout ce qui marche dans les Tarides. Taille-toi un chemin à travers les épines et rappelle à ces porcs qui règne sur ces terres !", en = "%s, beneath the giant brambles born of Agamaggan's blood, the quilboar have built their fortress. Charlga Razorflank prepares a war there against all who walk the Barrens. Hack your way through the thorns and remind these boars who rules this land!" },
    rol = { fr = "%s, au-dessus d'Undercity, les ruines de Lordaeron ne dorment pas : une puissance ancienne y rôde parmi les pierres brisées du trône de Terenas. La Garde de la Mort a besoin de lames qui ne tremblent pas. Rassemble les tiens et rends à la Dame noire le silence de sa cité !", en = "%s, above Undercity, the ruins of Lordaeron do not sleep: an ancient power prowls among the broken stones of Terenas' throne. The Deathguard needs blades that do not waver. Gather your own and return the silence of her city to the Dark Lady!" },
    scholo = { fr = "%s, à Caer Darrow, le Culte des damnés a fait d'une école de magie un atelier de nécromancie, sous la férule du Maître noir Gandling. Chaque nuit, de nouveaux morts se lèvent dans ses salles. Entre dans la Scholomance et ferme à jamais cette école de la mort !", en = "%s, at Caer Darrow, the Cult of the Damned has turned a school of magic into a workshop of necromancy, under the rule of Darkmaster Gandling. Every night, new dead rise in its halls. Enter Scholomance and close this school of death forever!" },
    sfk = { fr = "Le Sépulcre t'appelle, %s : au sommet de la colline, l'archimage Arugal a lâché ses worgens sur Silverpine, et la forêt entière hurle à la lune. Les Réprouvés veulent la tête de ce fou. Franchis les portes du donjon d'Ombrecroc et fais taire à jamais les crocs de l'ombre !", en = "The Sepulcher calls you, %s: atop the hill, Archmage Arugal has unleashed his worgen upon Silverpine, and the whole forest howls at the moon. The Forsaken want this madman's head. Break through the gates of Shadowfang Keep and silence the fangs of shadow forever!" },
    sm_arm = { fr = "%s, l'Armurerie abrite les plus féroces combattants de la Croisade, et leur champion Herod n'a jamais connu la défaite. Son tourbillon a fauché des légions. Prouve-lui que l'acier de la Horde est plus dur que sa foi !", en = "%s, the Armory shelters the Crusade's fiercest fighters, and their champion Herod has never known defeat. His whirlwind has cut down legions. Prove to him that Horde steel is harder than his faith!" },
    sm_cath = { fr = "%s, au cœur de la cathédrale, la Grande Inquisitrice Whitemane et le commandant Mograine mènent la Croisade d'une main de fer. Abats ces deux têtes, et le serpent écarlate tombera. Pour la Horde, frappe au centre du sanctuaire !", en = "%s, in the heart of the cathedral, High Inquisitor Whitemane and Commander Mograine lead the Crusade with an iron fist. Strike down these two heads, and the scarlet serpent will fall. For the Horde, strike at the center of the sanctuary!" },
    sm_gy = { fr = "%s, le Monastère écarlate est le cœur battant d'une croisade de fanatiques qui brûlent tout ce qui n'est pas eux. Dans son cimetière, même les morts refusent le repos. Entre par les tombes et venge ceux que la Croisade a tués !", en = "%s, the Scarlet Monastery is the beating heart of a crusade of fanatics who burn all that is not their own. In its graveyard, even the dead refuse to rest. Go in through the tombs and avenge those the Crusade has slain!" },
    sm_lib = { fr = "%s, derrière ces murs écarlates dorment les livres que la Croisade garde jalousement, sous la garde de l'arcaniste Doan. Les apothicaires d'Undercity attendent les cœurs de ces zélotes. Force la bibliothèque et que leur savoir serve enfin la Dame noire !", en = "%s, behind these scarlet walls sleep the books the Crusade jealously guards, watched over by Arcanist Doan. The apothecaries of Undercity await the hearts of these zealots. Storm the library and let their knowledge finally serve the Dark Lady!" },
    st = { fr = "%s, sous le marais des Chagrins, le temple d'Atal'Hakkar a sombré, et ses prêtres Atal'ai y appellent encore le dieu du sang, Hakkar. Les dragons verts eux-mêmes montent la garde, rongés par le cauchemar. Plonge dans le temple englouti et brise le rituel avant que le Dieu écorché ne renaisse !", en = "%s, beneath the Swamp of Sorrows, the temple of Atal'Hakkar lies sunken, and its Atal'ai priests still call upon the blood god, Hakkar. Even the green dragons stand guard there, gnawed by nightmare. Dive into the sunken temple and break the ritual before the Soulflayer is reborn!" },
    strat_live = { fr = "%s, Stratholme brûle encore depuis la nuit où Arthas l'a purgée, et la Croisade écarlate s'y accroche aux portes de l'enfer. Leur Grand Croisé cache un secret plus sombre que leur fanatisme. Traverse la ville en flammes et arrache le masque de leur chef !", en = "%s, Stratholme still burns from the night Arthas purged it, and the Scarlet Crusade clings to it at the gates of hell. Their Grand Crusader hides a secret darker than their fanaticism. Cross the burning city and tear the mask from their leader!" },
    strat_ud = { fr = "%s, dans la moitié morte de Stratholme, le baron Rivendare commande les légions du Fléau depuis sa citadelle. Ses abominations gardent chaque rue. Fends les rangs des morts et fais tomber le baron avant que le Fléau ne marche à nouveau !", en = "%s, in the dead half of Stratholme, Baron Rivendare commands the legions of the Scourge from his citadel. His abominations guard every street. Cleave through the ranks of the dead and bring down the baron before the Scourge marches again!" },
    ubrs = { fr = "%s, au sommet du pic, Rend Blackhand se proclame chef de guerre et le général Drakkisath couve une armée de dragons noirs. Seule une bande de dix guerriers aguerris peut y monter. Rapporte la tête de Rend à Thrall, et qu'Orgrimmar résonne de ton nom !", en = "%s, atop the spire, Rend Blackhand calls himself Warchief and General Drakkisath broods an army of black dragons. Only a band of ten hardened warriors can climb there. Bring Rend's head to Thrall, and let Orgrimmar ring with your name!" },
    uld = { fr = "%s, sous les Badlands dort Uldaman, un caveau des Titans que les nains Sombrefer pillent sans relâche. Au fond, le gardien Archaedas veille sur des secrets plus anciens que les races mortelles. Arrache ces trésors aux pilleurs avant qu'ils n'éveillent ce qui doit dormir !", en = "%s, beneath the Badlands sleeps Uldaman, a Titan vault the Shadowforge dwarves plunder without rest. In its depths, the guardian Archaedas watches over secrets older than the mortal races. Tear these treasures from the looters before they wake what must sleep!" },
    wc = { fr = "Écoute, %s, car la terre elle-même pleure : sous les Tarides, le rêve de Naralex s'est changé en cauchemar, et ses Druides du Croc rampent désormais comme des serpents dans l'ombre. Les anciens de Thunder Bluff ont posé leur espoir sur tes épaules. Réunis tes frères d'armes et descends dans la gueule du serpent : que le sang des traîtres rende la vie aux plaines !", en = "Listen, %s, for the land itself is weeping: beneath the Barrens, Naralex's dream has turned to nightmare, and his Druids of the Fang now slither like serpents in the dark. The elders of Thunder Bluff have placed their hope on your shoulders. Gather your brothers in arms and descend into the serpent's maw: let the blood of traitors bring the plains back to life!" },
    zf = { fr = "%s, au cœur de Tanaris, les trolls Sandfury de Zul'Farrak sacrifient quiconque s'approche de leurs murailles. Le chef Ukorz Sandscalp et leur bête sacrée, Gahz'rilla, attendent derrière les portes. Fends le désert et fais tomber la cité des sables !", en = "%s, in the heart of Tanaris, the Sandfury trolls of Zul'Farrak sacrifice anyone who nears their walls. Chief Ukorz Sandscalp and their sacred beast, Gahz'rilla, wait behind the gates. Cut through the desert and bring down the city of sand!" },
}
